use vstd::prelude::*;

verus! {
    fn solve(t: Vec<char>) -> (output: Vec<char>)
        requires
            t.len() < 0x1_0000_0000, // Ensure the length of the input vector is within bounds
        ensures
            output.len() == t.len(), // Ensure the output vector has the same length as the input
            forall|i: nat| 0 <= i < t.len() ==> output[i] == t[i], // Ensure each character in output matches the corresponding character in t
    {
        let mut output = Vec::with_capacity(t.len()); // Create a new vector with the same capacity as the input
        let mut index = 0; // Initialize the index to 0

        // Loop until we have processed all characters in the input vector
        while index < t.len()
            invariant
                index <= t.len(), // Ensure the index does not exceed the length of the input vector
                output.len() == index, // Ensure the output vector length matches the index
                forall|i: nat| 0 <= i < index ==> output[i] == t[i], // Ensure the output matches the input for processed characters
            decreases t.len() - index, // Decrease clause to ensure termination
        {
            output.push(t[index]); // Append the current character to the output
            index += 1; // Move to the next index
        }

        output // Return the constructed output vector
    }
}

